// ══════════════════════════════════════════════════════════════════
// LDI ALARM SIMULATOR — ใช้รหัสและความถี่จาก production log จริง
// Poisson process: 4.3 alarm/ชั่วโมง ทั้ง fleet (จาก 10,000 events/97 วัน)
// การกระจายเครื่อง: 4 เครื่องหลัก + 1 เครื่องที่แทบไม่มี alarm (ตามจริง)
// ══════════════════════════════════════════════════════════════════
const CUM = [["81501", 10.0], ["81101", 20.0], ["81102", 25.0], ["81201", 35.0], ["81203", 40.0], ["81204", 45.0], ["91009", 60.0], ["90005", 80.0], ["90004", 95.0], ["93004", 100.0]];
// น้ำหนักต่อเครื่อง (จากสัดส่วนจริง 3232/3130/2558/1063/17)
const MACHINES = [
    ["MOCK-LDI-01", 32.3], ["MOCK-LDI-04", 63.6],
    ["MOCK-LDI-05", 89.2], ["MOCK-LDI-06", 99.8], ["MOCK-LDI-09", 100.0]
];
// 4.3 alarm/ชม. = 0.001194 alarm/วินาที → tick 10 วิ = 0.01194 ต่อ tick
// เร่ง 20 เท่าเพื่อให้เห็นความเคลื่อนไหวบน dashboard ตอน demo
const RATE_PER_TICK = 0.01194 * 20;

function pick(table) {
    const x = Math.random() * 100;
    for (const [v, c] of table) if (x <= c) return v;
    return table[table.length - 1][0];
}

// Poisson: จำนวน alarm ใน tick นี้ (ปกติ 0 หรือ 1 บางครั้ง 2)
let n = 0, L = Math.exp(-RATE_PER_TICK), p = 1;
do { p *= Math.random(); n++; } while (p > L);
n = n - 1;
if (n === 0) { node.status({ fill: 'grey', shape: 'ring', text: 'no alarm' }); return null; }

const rows = [];
const now = Date.now();
for (let k = 0; k < n; k++) {
    const ts = new Date(now - Math.floor(Math.random() * 9000));
    const eq = pick(MACHINES);
    const code = pick(CUM);
    rows.push({
        logid: 'SIM-ALM-' + now + '-' + k,
        logdate: ts.toISOString(),
        errorcode: code,
        errortime: ts.toISOString().replace('T', ' ').substring(0, 19),
        equipmentid: eq,
        factory: Math.random() < 0.75 ? '2' : '3',
        process: ['DF INNER', 'DF OUTER', 'SM'][Math.floor(Math.random() * 3)]
    });
}
msg.payload = rows;
node.status({ fill: 'yellow', shape: 'dot',
    text: rows.length + ' alarm: ' + rows.map(r => r.errorcode).join(',') });
return msg;

const pool = global.get('pgPool');
const rows = msg.payload || [];
if (!pool || rows.length === 0) return null;
const cols = ['logid','logdate','errorcode','errortime','equipmentid','factory','process'];
const ph = rows.map((_, i) => '(' + cols.map((_, j) => '$' + (i * 7 + j + 1)).join(',') + ')').join(',');
const params = [];
for (const r of rows) for (const c of cols) params.push(r[c]);
const sql = 'INSERT INTO public.ldi_alarm_log (' + cols.join(',') + ') VALUES ' + ph +
            ' ON CONFLICT (logdate, logid) DO NOTHING';
pool.query(sql, params, function (err) {
    if (err) { node.error('Alarm sim INSERT failed: ' + err.message); return; }
    node.log('Alarm sim: inserted ' + rows.length);
});
return null;
